<script lang="ts">
 import {goto} from '$app/navigation';import {useQuery,useConvexClient} from 'convex-svelte';import {useAuth} from '@mmailaender/convex-better-auth-svelte/svelte';import {api} from '$convex/_generated/api';import {naira} from '$ui/format';
 let {slug}:{slug:string}=$props();const client=useConvexClient(),auth=useAuth(),pack=useQuery(api.portal.publicPack,()=>({slug})),access=useQuery(api.portal.packAccess,()=>auth.isAuthenticated&&pack.data?{packId:pack.data._id}:'skip');let busy=$state(false),error=$state('');
 async function buy(){if(!auth.isAuthenticated){await goto('/login?next='+encodeURIComponent('/library/'+slug));return;}busy=true;error='';try{const id=await client.mutation(api.checkout.order,{kind:'pack',refId:pack.data!._id});await goto('/checkout/'+id);}catch(e){error=e instanceof Error?e.message:'Unable to create order.';}finally{busy=false;}}
</script>
<svelte:head><title>{pack.data?.title??'SchoolXense Library'} · SchoolXense Library</title><meta name="description" content={pack.data?`${pack.data.subject} ${pack.data.exam} study resource with ${pack.data.pages} pages.`:'Reviewed SchoolXense study resources.'}/></svelte:head>
{#if pack.isLoading}<p class="max-w-[1100px] mx-auto p-8 muted">Loading resource…</p>{:else if !pack.data}<section class="max-w-[1100px] mx-auto p-8"><h1 class="text-3xl font-semibold">Resource unavailable</h1><a href="/library" class="ctl mt-4">Return to library</a></section>{:else}<section class="max-w-[1100px] mx-auto px-4 sm:px-6 pt-10 grid lg:grid-cols-[1.5fr_1fr] gap-6"><div><a class="link text-sm" href="/library">← Library</a><h1 class="text-3xl font-semibold mt-4">{pack.data.title}</h1><p class="muted mt-2">{pack.data.subject} · {pack.data.exam} · {pack.data.pages} pages · by {pack.data.authorName}</p><section class="panel p-6 mt-5"><p class="eyebrow">Preview</p><ol class="grid gap-3 mt-4">{#each pack.data.preview as line,i}<li><span class="num muted mr-3">{i+1}</span>{line}</li>{/each}</ol></section></div><aside class="panel p-5 h-fit"><p class="num text-3xl font-semibold">{naira(Number(pack.data.price))}</p>{#if access.data}<a class="ctl ctl-primary mt-5" href={`/api/media/documents/${access.data.key}`}>Download purchased PDF</a>{:else}<button class="ctl ctl-primary mt-5" disabled={busy} onclick={buy}>Purchase securely</button>{/if}{#if error}<p role="alert" class="mt-3">{error}</p>{/if}<p class="text-xs muted mt-4">Downloads require the signed-in purchasing account. Payment access is granted only after server verification.</p></aside></section>{/if}
